SINA_SMART["infect-antifungals"] = {"lecture":"infect-antifungals","title":"Antifungal drugs for invasive fungal infections","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-antifungals:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"infect-antifungals:e0","text":"Four classes: polyenes, azoles, echinocandins, 5-flucytosine.","topic":"Classes and mechanisms","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e1","text":"Amphotericin binds ergosterol; azoles block its synthesis; echinocandins block β-D-glucan.","topic":"Classes and mechanisms","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e2","text":"Amphotericin B: broad, fungicidal, IV only; nephrotoxic, ↓K ↓Mg; lipid forms safer.","topic":"Amphotericin B and flucytosine","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e3","text":"5-FC: always combined (cryptococcosis); marrow toxicity.","topic":"Amphotericin B and flucytosine","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e4","text":"Fluconazole: Candida + Cryptococcus, not Aspergillus or C. krusei.","topic":"Azoles","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e5","text":"Mucorales: amphotericin, posaconazole, isavuconazole.","topic":"Azoles","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e6","text":"Azoles: interactions, loading dose, hepatotoxicity, QT (not isavuconazole).","topic":"Azoles","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e7","text":"Voriconazole: visual hallucinations, photosensitivity, skin cancer.","topic":"Azoles","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-antifungals:e8","text":"Echinocandins: IV, poor CSF/urine, not Cryptococcus; few interactions.","topic":"Echinocandins","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"20di8t":"a","10sdcuo":"a","sdxqzh":"a","12imbc5":"a","72hjx9":"a","7bstiy":"a","1p4ziga":"a","wmr6gp":"a","1cg47bw":"a","ng2f3y":"a","m42u20":"a","14qwgt5":"a","180edyt":"a","lui7bb":"a","iixahh":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-antifungals:s0":{"s":0,"u":["Antifungals destroy fungi by targeting structures that fungal cells have and human cells lack.","Topical antifungals treat limited, non-recurrent superficial mycoses of skin, scalp and mucosa; systemic antifungals treat invasive (visceral or septicaemic) mycoses and extensive, recurrent or chronic superficial ones."],"dp":[]},"infect-antifungals:e0":{"s":1,"u":["Four classes: polyenes, azoles, echinocandins, 5-flucytosine.","Four classes: polyenes (amphotericin B) bind ergosterol in the membrane (resistance rare); azoles (fluconazole, itraconazole, voriconazole, posaconazole, isavuconazole) inhibit ergosterol synthesis (resistance by target change or efflux); echinocandins (caspofungin, anidulafungin, micafungin) inhibit β-D-glucan synthesis in the cell wall; pyrimidines (5-flucytosine) inhibit DNA/RNA synthesis ."],"dp":[{"h":"Why echinocandins fail in cryptococcal meningitis","t":"Cryptococcus has little β-glucan in its wall, so echinocandins barely affect it, and these large molecules also penetrate poorly into the cerebrospinal fluid. Cryptococcal meningitis is therefore treated with amphotericin B plus flucytosine, which reach the CSF and act on the organism. Source: the lecture's echinocandin and 5-FC slides."}]},"infect-antifungals:e1":{"s":1,"u":["Amphotericin binds ergosterol; azoles block its synthesis; echinocandins block β-D-glucan.","Four classes: polyenes (amphotericin B) bind ergosterol in the membrane (resistance rare); azoles (fluconazole, itraconazole, voriconazole, posaconazole, isavuconazole) inhibit ergosterol synthesis (resistance by target change or efflux); echinocandins (caspofungin, anidulafungin, micafungin) inhibit β-D-glucan synthesis in the cell wall; pyrimidines (5-flucytosine) inhibit DNA/RNA synthesis ."],"dp":[{"h":"Why antifungals are harder to design than antibiotics","t":"Fungi are eukaryotes like us: their ribosomes, nuclei and metabolism resemble human ones, so few targets are truly unique. The main exploitable differences are ergosterol instead of cholesterol in the membrane and a β-glucan cell wall, which is exactly what the four classes attack. Even so, amphotericin binds cholesterol a little, which explains its kidney toxicity. Source: the lecture's mechanism slide."}]},"infect-antifungals:e2":{"s":2,"u":["Amphotericin B: broad, fungicidal, IV only; nephrotoxic, ↓K ↓Mg; lipid forms safer.","Lipid forms cause fewer effects.","Amphotericin B : broad spectrum (Aspergillus fumigatus, Mucorales, Fusarium, Candida including krusei and glabrata, Cryptococcus; not A. terreus or Scedosporium prolificans); fungicidal ."],"dp":[]},"infect-antifungals:e3":{"s":2,"u":["5-FC: always combined (cryptococcosis); marrow toxicity.","Toxicity: GI (pain, pseudomembranous colitis with perforation risk), liver cytolysis, bone marrow (leucopenia, agranulocytosis, pancytopenia)."],"dp":[]},"infect-antifungals:e4":{"s":3,"u":["Fluconazole: Candida + Cryptococcus, not Aspergillus or C. krusei.","Spectrum: fluconazole covers Candida albicans and parapsilosis and Cryptococcus but not Aspergillus or C. krusei; itraconazole, voriconazole, posaconazole and isavuconazole cover Aspergillus ; only posaconazole and isavuconazole cover Mucorales .","Fungicidal on Aspergillus, fungistatic on Candida."],"dp":[]},"infect-antifungals:e5":{"s":3,"u":["Mucorales: amphotericin, posaconazole, isavuconazole.","Spectrum: fluconazole covers Candida albicans and parapsilosis and Cryptococcus but not Aspergillus or C. krusei; itraconazole, voriconazole, posaconazole and isavuconazole cover Aspergillus ; only posaconazole and isavuconazole cover Mucorales .","With meals (fat): itraconazole capsules, posaconazole solution; outside meals : itraconazole solution, voriconazole; no influence: fluconazole, posaconazole tablets, isavuconazole."],"dp":[]},"infect-antifungals:e6":{"s":3,"u":["Azoles: interactions, loading dose, hepatotoxicity, QT (not isavuconazole).","Features: many drug interactions (liver metabolism), loading dose needed, variable serum levels, diet affects absorption."],"dp":[]},"infect-antifungals:e7":{"s":3,"u":["Voriconazole: visual hallucinations, photosensitivity, skin cancer.","Toxicity: hepatotoxicity (more with voriconazole), rare rash, QT prolongation (itra, posa, vori; isavuconazole shortens it); itraconazole: hypokalaemia, hypertension, leg oedema; voriconazole : visual hallucinations , neuropathy, photosensitivity and skin cancers with prolonged use."],"dp":[]},"infect-antifungals:e8":{"s":4,"u":["Echinocandins: IV, poor CSF/urine, not Cryptococcus; few interactions.","Concentration-dependent; poor CSF and urine diffusion ; IV only (oral bioavailability 0%).","Well tolerated: liver abnormalities, few drug interactions ."],"dp":[]}},"meta":{"20di8t":{"a":"recall","vg":"infect-antifungals:s0/recall/1"},"10sdcuo":{"a":"recall","vg":"infect-antifungals:e1/recall/1"},"sdxqzh":{"a":"recall","vg":"infect-antifungals:e1/recall/1"},"12imbc5":{"a":"recall","vg":"infect-antifungals:e8/recall/1"},"72hjx9":{"a":"recall","vg":"infect-antifungals:e3/recall/1"},"7bstiy":{"a":"relationship","vg":"infect-antifungals:e2/relationship/1"},"1p4ziga":{"a":"recall","vg":"infect-antifungals:e3/recall/2"},"wmr6gp":{"a":"recall","vg":"infect-antifungals:e3/recall/3"},"1cg47bw":{"a":"recall","vg":"infect-antifungals:e4/recall/1"},"ng2f3y":{"a":"recall","vg":"infect-antifungals:e5/recall/1"},"m42u20":{"a":"recall","vg":"infect-antifungals:e5/recall/2"},"14qwgt5":{"a":"recall","vg":"infect-antifungals:e7/recall/1"},"180edyt":{"a":"recall","vg":"infect-antifungals:e0/recall/1"},"lui7bb":{"a":"recall","vg":"infect-antifungals:e4/recall/1"},"iixahh":{"a":"recall","vg":"infect-antifungals:e8/recall/2"}},"explRev":"350269f46cf2"};
